import{_ as i,H as l,f as a,i as n}from"./chunks/framework.BH2BK_3i.js";const R=JSON.parse(`{"title":"O'ReillyMedia,Inc.介绍","description":"","frontmatter":{},"headers":[{"level":2,"title":"业界评论","slug":"业界评论","link":"#业界评论","children":[]}],"relativePath":"黑客与画家/O'ReillyMedia,Inc.介绍.md","filePath":"黑客与画家/O'ReillyMedia,Inc.介绍.md","lastUpdated":1795561874000}`),r={name:"黑客与画家/O'ReillyMedia,Inc.介绍.md"};function t(d,e,o,p,s,c){return l(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="o-reillymedia-inc-介绍" tabindex="-1">O&#39;ReillyMedia,Inc.介绍 <a class="header-anchor" href="#o-reillymedia-inc-介绍" aria-label="Permalink to &quot;O&#39;ReillyMedia,Inc.介绍&quot;">​</a></h1><p>O&#39;Reilly 以“分享创新知识、改变世界”为己任。40 多年来我们一直向企业、个人提供成功 所必需之技能及思想，激励他们创新并做得更好。</p><p>O&#39;Reilly 业务的核心是独特的专家及创新者网络，众多专家及创新者通过我们分享知识。我 们的在线学习（Online Learning）平台提供独家的直播培训、图书及视频，使客户更容易获 取业务成功所需的专业知识。几十年来 O&#39;Reilly 图书一直被视为学习开创未来之技术的权威 资料。我们每年举办的诸多会议是活跃的技术聚会场所，来自各领域的专业人士在此建立联系，讨论最佳实践并发现可能影响技术行业未来的新趋势。</p><p>我们的客户渴望做出推动世界前进的创新之举，我们希望能助他们一臂之力。</p><h2 id="业界评论" tabindex="-1">业界评论 <a class="header-anchor" href="#业界评论" aria-label="Permalink to &quot;业界评论&quot;">​</a></h2><ul><li><p>“O&#39;Reilly Radar 博客有口皆碑。”——Wired</p></li><li><p>“O&#39;Reilly 凭借一系列非凡想法（真希望当初我也想到了）建立了数百万美元的业务。”——Business 2.0</p></li><li><p>“O&#39;Reilly Conference 是聚集关键思想领袖的绝对典范。”——CRN</p></li><li><p>“一本 O&#39;Reilly 的书就代表一个有用、有前途、需要学习的主题。”——Irish Times</p></li><li><p>“Tim 是位特立独行的商人，他不光放眼于最长远、最广阔的领域，并且切实地按 照 YogiBerra 的建议去做了：‘如果你在路上遇到岔路口，那就走小路。&#39;回顾过 去，Tim 似乎每一</p></li><li><p>次都选择了小路，而且有几次都是一闪即逝的机会，尽管大路也不错。”——Linux Journal</p></li></ul>',6)])])}const m=i(r,[["render",t]]);export{R as __pageData,m as default};
